import{z as s,x as d,o as n,c as B,q as r,j as i,D as E,d as e,s as l,S as A,b as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Goodman 傅里叶光学","description":"","frontmatter":{"title":"Goodman 傅里叶光学","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/goodman-fourier-optics.md","filePath":"litho/goodman-fourier-optics.md","lastUpdated":1791063341000}'),m={name:"litho/goodman-fourier-optics.md"};function p(h,a,u,f,D,c){const t=d("Mermaid");return n(),B("div",null,[a[2]||(a[2]=r('<h1 id="goodman-傅里叶光学" tabindex="-1">Goodman 傅里叶光学 <a class="header-anchor" href="#goodman-傅里叶光学" aria-label="Permalink to &quot;Goodman 傅里叶光学&quot;">​</a></h1><div class="epigraph"><p>透镜是傅里叶变换器：物的频谱在焦面排开，光瞳做乘法窗，像是被截断频谱的干涉。光刻投影是这本书里的相干 / 部分相干成像，而不是另一门数学。</p><footer>—— Joseph W. Goodman, Introduction to Fourier Optics</footer></div><p>附录对照，不插入主干。<a href="/litho/vanschoot-high-na-paper">上一课</a>对照了 High-NA 变形光学论文。本篇对照 Goodman《傅里叶光学导论》：主干 <a href="/litho/abbe-imaging">阿贝成像</a> 与 <a href="/litho/diffraction-spatial-freq">衍射与空间频率</a> 已经按课序把「频谱被光瞳低通」写进产线语言；书则从标量衍射、傅里叶变换透镜和相干传递函数系统讲起。这里只映射章节与树，避免每一课再从惠更斯原理重写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干禁止百科：阿贝课从掩模频谱接到投影光瞳，立刻走向 NA 与产线。Goodman 的读者可能先读 Fresnel / Fraunhofer，再读 4f 系统，再读成像。附录的缺口是：如何引用这本书而不把树打乱成教材目录。</p><p>van Schoot 论文用的是 EUV 多层与倍率约束；Goodman 不管 13.5 nm。两者都是附录，分工不同：一篇对照产品几何论证，一篇对照标量傅里叶成像的共同语言。</p><h3 id="与阿贝课的分工" tabindex="-1">与阿贝课的分工 <a class="header-anchor" href="#与阿贝课的分工" aria-label="Permalink to &quot;与阿贝课的分工&quot;">​</a></h3><p>阿贝课已经说：物衍射 → 光瞳截断 → 像面干涉。Goodman 把同一件事写成算子：相干脉冲响应是光瞳的傅里叶逆，传递函数是缩放后的光瞳。主干用阿贝把直觉钉在显微镜/投影上；附录用 Goodman 指出符号从哪来。不要在主干再抄一章衍射积分。</p><p><span class="marginnote">Goodman 以标量、单色为主。光刻的部分相干、矢量、薄膜栈在 Hopkins / 矢量成像课。不要把书的相干传递函数直接当 OPC 核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表（概念级，不代替读书）：衍射与空间频率 ↔ 树的衍射课；傅里叶透镜与阿贝 ↔ 阿贝课；相干成像与截止 ↔ <a href="/litho/lens-na">透镜 NA</a>；抽样与空间带宽 ↔ 计算光刻离散化的背景，但不在主干展开成通信课。部分相干在 Goodman 有专章，主干对应 <a href="/litho/hopkins-tcc">Hopkins</a> 与 SMO，附录只点名「书里有，树里另叶」。</p><p><span class="marginnote">术语翻译：相干传递函数（CTF）可以读成「光瞳的缩放替身」——把光瞳的形状沿频率轴按 \\(\\lambda f\\) 缩放，就得到一张「哪些空间频率放行、哪些拦截」的滤镜说明书；「低通」指只放行低空间频率（粗结构），拦下高空间频率（细节）。</span></p><p><span class="marginnote">数字实例：\\(\\mathrm{NA}=1.35\\)、\\(\\lambda=193\\) nm 时，相干截止频率 \\(\\mathrm{NA}/\\lambda \\approx 7000\\ \\mathrm{mm}^{-1}\\)，对应最小可分辨半周期 \\(\\lambda/(2\\mathrm{NA}) \\approx 72\\) nm。掩模上比这更细的纹理，级次根本进不了光瞳——不是「印得淡」，而是压根没有信息到达晶圆。</span></p><p>High-NA 变形倍率不是 Goodman 的例题。读 van Schoot 需要的几何光学与角谱，书提供角谱语言，不提供 4×/8×。</p><h3 id="不要当课程序列" tabindex="-1">不要当课程序列 <a class="header-anchor" href="#不要当课程序列" aria-label="Permalink to &quot;不要当课程序列&quot;">​</a></h3><p>若按 Goodman 章节当主干，读者会在胶、套刻、EUV 源之前先读完标量衍射全书。树的选择是：只用阿贝+衍射两叶把傅里叶钉住，其余进产线。本附录防止「缺一本教材」的焦虑，也防止把教材插回 EUV 光源课序。</p>',16)),(n(),i(A,null,{default:E(()=>[l(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E7%89%A9%EF%BC%9A%E6%8E%A9%E6%A8%A1%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20FT%5B%22%E9%80%8F%E9%95%9C%E4%BD%9C%E5%82%85%E9%87%8C%E5%8F%B6%E5%8F%98%E6%8D%A2%EF%BC%9A%E9%A2%91%E8%B0%B1%E5%9C%A8%E7%84%A6%E9%9D%A2%E6%8E%92%E5%BC%80%22%5D%0A%20%20FT%20--%3E%20PUP%5B%22%E5%85%89%E7%9E%B3%20%3D%20%E4%BD%8E%E9%80%9A%E7%AA%97%EF%BC%9A%E5%8F%AA%E6%94%BE%E8%A1%8C%E6%88%AA%E6%AD%A2%E9%A2%91%E7%8E%87%E4%BB%A5%E5%86%85%E7%9A%84%E7%BA%A7%E6%AC%A1%22%5D%0A%20%20PUP%20--%3E%20INV%5B%22%E7%AC%AC%E4%BA%8C%E5%8F%AA%E9%80%8F%E9%95%9C%E4%BD%9C%E9%80%86%E5%8F%98%E6%8D%A2%22%5D%0A%20%20INV%20--%3E%20IMG%5B%22%E5%83%8F%20%3D%20%E8%A2%AB%E6%88%AA%E6%96%AD%E9%A2%91%E8%B0%B1%E7%9A%84%E5%B9%B2%E6%B6%89%E5%9B%BE%E6%A0%B7%22%5D%0A%20%20PUP%20--%20%22%E7%BA%A7%E6%AC%A1%E8%A2%AB%E6%8B%A6%22%20--%3E%20LOSS%5B%22%E7%BB%86%E8%8A%82%E4%B8%A2%E5%A4%B1%20%E2%86%92%20%E5%AF%B9%E6%AF%94%E5%BA%A6%E4%B8%8E%20CD%20%E5%81%8F%E7%A7%BB%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"投影光刻的掩模频谱、光瞳函数、像强度，正是 Goodman 成像一章的对象；部分相干把互强度换成双线性核，书与 Hopkins 论文在这里会合。OPC 把这个算子求逆，书不负责求逆。EUV 多层反射、三维掩模超出标量薄屏，书的 Kirchhoff 假设要让位给严格电磁课。",-1)),a[5]||(a[5]=o("p",null,[o("span",{class:"marginnote"},"直觉类比：光瞳低通就像给照片开「磨皮滤镜」——粗轮廓（低频）原样保留，细纹与噪点（高频）被抹掉；线条边缘因此变「圆」。OPC 的一大半工作，就是预先改图形，让图形过完这个滤镜后像面上仍出现想要的形状。")],-1)),a[6]||(a[6]=o("p",null,"因此：Goodman 解释「为什么是低通、为什么有截止频率」；阿贝课解释「为什么光刻师从这一句出发」；产品课解释「截止之后工厂还缺什么」。",-1)),a[7]||(a[7]=o("p",null,[o("span",{class:"marginnote"},"引用格式用书名与作者，不要编造版次年份当唯一标准，更不要给这本书捏一个 arXiv 号。")],-1)),(n(),i(A,null,{default:E(()=>[l(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOK%5B%22Goodman%20%E5%82%85%E9%87%8C%E5%8F%B6%E5%85%89%E5%AD%A6%22%5D%20--%3E%20ABBE%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E9%98%BF%E8%B4%9D%20%2F%20%E8%A1%8D%E5%B0%84%22%5D%0A%20%20BOOK%20--%3E%20HOP%5B%22%E5%AF%B9%E7%85%A7%3A%20Hopkins%20%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%22%5D%0A%20%20VS%5B%22van%20Schoot%20High-NA%22%5D%20--%3E%20GEO%5B%22%E5%8F%98%E5%BD%A2%E5%80%8D%E7%8E%87%E5%87%A0%E4%BD%95%22%5D%0A%20%20ABBE%20--%3E%20GEO%0A%20%20BOOK%20-.-%3E%7C%22%E4%B8%8D%E6%8F%92%E5%85%A5%22%7C%20SRC%5B%22EUV%20%E5%85%89%E6%BA%90%E4%B8%BB%E5%B9%B2%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Fresnel 积分抄进正文，也不用书的习题当 TAPOUT。矢量、多层、胶、随机效应都不在 Goodman 的主方程里。书里的空间滤波例子可以对照光瞳优化的直觉，但 SMO 的部分相干代价函数不在这本书的习题里。后课 Naulleau 随机效应论文对照胶与光子统计，与本篇的标量成像正交。</p><p>不要发明章节与树叶的一一编号表。映射保持到「概念 ↔ 已有叶」。</p><p><span class="marginnote">Tufte 课程序列优先于任何教材目录。书是对照，不是上一课的续章。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Goodman 提供标量傅里叶成像的共同语言；主干已用阿贝/衍射两叶吸收直觉。</li><li>附录只映射，不把教材插进 EUV 或 OPC 课序。</li><li>部分相干、矢量、多层要另叶；不要用相干传递函数冒充 OPC 核。</li><li>与 van Schoot 对照篇分工：一书一产品光学论文。</li><li>EUV 多层与三维掩模超出标量薄屏，要让位给严格电磁课。</li><li>出处：Goodman, <em>Introduction to Fourier Optics</em>；主干阿贝 / 衍射课。</li></ul>',6))])}const P=s(m,[["render",p]]);export{F as __pageData,P as default};
